Hom}(\mathsf{E}_\tau(\mathcal{E}_1)[k],\mathsf{E}_\tau(\mathcal{E}_2)[l])\otimesHom}(\mathsf{E}_\tau(\mathcal{E}_0),\mathsf{E}_\tau(\mathcal{E}_1)[k])\arrow[r, "\circ"'] & Hom}(\mathsf{E}_\tau(\mathcal{E}_0),\mathsf{E}_\tau(\mathcal{E}_2)[l])
