\[
\|\varphi\|_{Hofer}}
:=\inf\left\{\|H\|_{Hofer}}\;\middle|\;
\begin{array}{l}
H\ 是生成一条连接}\ \mathbf{1}\ 与}\ \varphi\ 的道路}\\
